@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications { get; set; }
    private bool PushNotifications { get; set; }
    private bool WeeklyDigest { get; set; }
    private List<string> MutedChannels { get; set; } = new();

    private static readonly string[] AvailableChannels = { "general", "marketing", "engineering", "design", "announcements" };

    private string? _statusMessage;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            MutedChannels = new List<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!muted)
            MutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
        await OnSave.InvokeAsync(updated);
        _statusMessage = "Preferences saved successfully!";
    }
}

@namespace sv_58dc9aa02a394621ab05cf4b9500313d.Components.Pages.Settings
@using sv_58dc9aa02a394621ab05cf4b9500313d.Services

<div class="security-section">
    <h4 class="mb-4">Security Settings</h4>

    @if (Settings is not null)
    {
        <!-- Change Password Panel -->
        <div class="card mb-4">
            <div class="card-header d-flex justify-content-between align-items-center"
                 style="cursor:pointer" @onclick="() => _passwordExpanded = !_passwordExpanded">
                <span><strong>Change Password</strong></span>
                <i class="bi @(_passwordExpanded ? "bi-chevron-up" : "bi-chevron-down")"></i>
            </div>
            @if (_passwordExpanded)
            {
                <div class="card-body">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" @bind="_confirmPassword" />
                    </div>
                    @if (!string.IsNullOrEmpty(_passwordError))
                    {
                        <div class="alert alert-danger">@_passwordError</div>
                    }
                    @if (!string.IsNullOrEmpty(_passwordSuccess))
                    {
                        <div class="alert alert-success">@_passwordSuccess</div>
                    }
                    <button class="btn btn-warning" @onclick="UpdatePassword">Update Password</button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="card mb-4">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <strong>Two-Factor Authentication</strong>
                    <span class="badge @(Settings.TwoFactorEnabled ? "bg-success" : "bg-secondary") ms-2">
                        @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" checked="@Settings.TwoFactorEnabled" disabled />
                </div>
            </div>
            @if (Settings.LastPasswordChange.HasValue)
            {
                <div class="card-footer text-muted small">
                    Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </div>
            }
        </div>

        <!-- Active Sessions -->
        <div class="card">
            <div class="card-header"><strong>Active Sessions</strong></div>
            <div class="card-body p-0">
                <table class="table table-hover mb-0">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in Settings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (session.Id != Settings.Sessions.FirstOrDefault()?.Id)
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="badge bg-info">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (_sessionToRevoke is not null)
        {
            <div class="modal d-block" tabindex="-1" style="background:rgba(0,0,0,0.5)">
                <div class="modal-dialog modal-dialog-centered">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">Revoke Session</h5>
                            <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                        </div>
                        <div class="modal-body">
                            <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                        </div>
                        <div class="modal-footer">
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                            <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke Session</button>
                        </div>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private string? _passwordSuccess;
    private ActiveSession? _sessionToRevoke;

    private async Task UpdatePassword()
    {
        _passwordError = null;
        _passwordSuccess = null;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "All fields are required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
        _passwordSuccess = "Password updated successfully!";
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
    }

    private void PromptRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.Now - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

@namespace sv_58dc9aa02a394621ab05cf4b9500313d.Components.Pages.Settings
@using sv_58dc9aa02a394621ab05cf4b9500313d.Services

<div class="appearance-section">
    <h4 class="mb-4">Appearance Settings</h4>

    <div class="row">
        <div class="col-md-7">
            <!-- Theme -->
            <div class="mb-4">
                <label class="form-label fw-bold">Theme</label>
                <div>
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="@($"theme-{theme}")" value="@theme"
                                   checked="@(Theme == theme)"
                                   @onchange="() => Theme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
                </div>
            </div>

            <!-- Font Size -->
            <div class="mb-4">
                <label class="form-label fw-bold">Font Size</label>
                <div>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="@($"fs-{size}")" value="@size"
                                   checked="@(FontSize == size)"
                                   @onchange="() => FontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>
            </div>

            <!-- Language -->
            <div class="mb-4">
                <label class="form-label fw-bold">Language</label>
                <select class="form-select" @bind="Language">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>

            @if (!string.IsNullOrEmpty(_statusMessage))
            {
                <div class="alert alert-success mt-3">@_statusMessage</div>
            }
        </div>

        <!-- Live Preview -->
        <div class="col-md-5">
            <div class="card">
                <div class="card-header"><strong>Live Preview</strong></div>
                <div class="card-body @GetPreviewClasses()" style="@GetPreviewStyles()">
                    <h5 style="@GetPreviewFontStyle()">Sample Heading</h5>
                    <p style="@GetPreviewFontStyle()">This is how your content will look with the selected appearance settings.</p>
                    <button class="btn btn-sm btn-primary">Sample Button</button>
                    <div class="mt-2">
                        <span class="badge bg-secondary">@Language</span>
                        <span class="badge bg-info ms-1">@FontSize</span>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme { get; set; } = "Light";
    private string FontSize { get; set; } = "Medium";
    private string Language { get; set; } = "English";
    private bool CompactMode { get; set; }

    private string? _statusMessage;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
        _statusMessage = "Appearance saved successfully!";
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        if (Theme == "Dark") classes.Add("bg-dark text-light");
        if (CompactMode) classes.Add("p-2");
        else classes.Add("p-3");
        return string.Join(" ", classes);
    }

    private string GetPreviewStyles()
    {
        var styles = new List<string>();
        if (Theme == "Dark") styles.Add("background-color:#1a1a2e;color:#e0e0e0");
        else if (Theme == "System") styles.Add("background-color:#f0f0f0");
        return string.Join(";", styles);
    }

    private string GetPreviewFontStyle() => FontSize switch
    {
        "Small" => "font-size:0.85rem",
        "Large" => "font-size:1.25rem",
        _ => "font-size:1rem"
    };
}

