{"file_text": "@namespace sv_58dc9aa02a394621ab05cf4b9500313d.Components.Pages.Settings
@using sv_58dc9aa02a394621ab05cf4b9500313d.Services

<div class="appearance-section">
    <h4 class="mb-4">Appearance Settings</h4>

    <div class="row">
        <div class="col-md-7">
            <!-- Theme -->
            <div class="mb-4">
                <label class="form-label fw-bold">Theme</label>
                <div>
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="@($"theme-{theme}")" value="@theme"
                                   checked="@(Theme == theme)"
                                   @onchange="() => Theme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
                </div>
            </div>

            <!-- Font Size -->
            <div class="mb-4">
                <label class="form-label fw-bold">Font Size</label>
                <div>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="@($"fs-{size}")" value="@size"
                                   checked="@(FontSize == size)"
                                   @onchange="() => FontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>
            </div>

            <!-- Language -->
            <div class="mb-4">
                <label class="form-label fw-bold">Language</label>
                <select class="form-select" @bind="Language">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>

            @if (!string.IsNullOrEmpty(_statusMessage))
            {
                <div class="alert alert-success mt-3">@_statusMessage</div>
            }
        </div>

        <!-- Live Preview -->
        <div class="col-md-5">
            <div class="card">
                <div class="card-header"><strong>Live Preview</strong></div>
                <div class="card-body @GetPreviewClasses()" style="@GetPreviewStyles()">
                    <h5 style="@GetPreviewFontStyle()">Sample Heading</h5>
                    <p style="@GetPreviewFontStyle()">This is how your content will look with the selected appearance settings.</p>
                    <button class="btn btn-sm btn-primary">Sample Button</button>
                    <div class="mt-2">
                        <span class="badge bg-secondary">@Language</span>
                        <span class="badge bg-info ms-1">@FontSize</span>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme { get; set; } = "Light";
    private string FontSize { get; set; } = "Medium";
    private string Language { get; set; } = "English";
    private bool CompactMode { get; set; }

    private string? _statusMessage;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
        _statusMessage = "Appearance saved successfully!";
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        if (Theme == "Dark") classes.Add("bg-dark text-light");
        if (CompactMode) classes.Add("p-2");
        else classes.Add("p-3");
        return string.Join(" ", classes);
    }

    private string GetPreviewStyles()
    {
        var styles = new List<string>();
        if (Theme == "Dark") styles.Add("background-color:#1a1a2e;color:#e0e0e0");
        else if (Theme == "System") styles.Add("background-color:#f0f0f0");
        return string.Join(";", styles);
    }

    private string GetPreviewFontStyle() => FontSize switch
    {
        "Small" => "font-size:0.85rem",
        "Large" => "font-size:1.25rem",
        _ => "font-size:1rem"
    };
}
