@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Bio { get; set; } = "";
    private string AvatarUrl { get; set; } = "";

    private string? _statusMessage;
    private bool _isSuccess;

    protected override void OnParametersSet()
    {
        if (Profile is not null && string.IsNullOrEmpty(DisplayName) && !_isDirty)
        {
            LoadFromProfile();
        }
    }

    private bool _isDirty;

    private void LoadFromProfile()
    {
        if (Profile is null) return;
        DisplayName = Profile.DisplayName;
        Email = Profile.Email;
        Bio = Profile.Bio;
        AvatarUrl = Profile.AvatarUrl;
        _isDirty = false;
    }

    private async Task SaveChanges()
    {
        var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
        await OnSave.InvokeAsync(updated);
        _isDirty = false;
        _statusMessage = "Profile saved successfully!";
        _isSuccess = true;
    }

    private void DiscardChanges()
    {
        LoadFromProfile();
        _statusMessage = "Changes discarded.";
        _isSuccess = false;
    }
}

