arguments.file_text:
@page "/settings"
@namespace sv_58dc9aa02a394621ab05cf4b9500313d.Components.Pages.Settings
@using sv_58dc9aa02a394621ab05cf4b9500313d.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="container-fluid py-4">
    <h2 class="mb-4">Settings</h2>
    <div class="row">
        <div class="col-md-3 col-lg-2">
            <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="SetActiveSection" />
        </div>
        <div class="col-md-9 col-lg-10">
            @if (_loading)
            {
                <div class="d-flex justify-content-center py-5">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
            else
            {
                @switch (_activeSection)
                {
                    case "Profile":
                        <ProfileSection Profile="@_profile" OnSave="SaveProfile" />
                        break;
                    case "Notifications":
                        <NotificationsSection Prefs="@_notificationPrefs" OnSave="SaveNotifications" />
                        break;
                    case "Security":
                        <SecuritySection Settings="@_securitySettings"
                                         OnChangePassword="ChangePassword"
                                         OnRevokeSession="RevokeSession" />
                        break;
                    case "Appearance":
                        <AppearanceSection Settings="@_appearanceSettings" OnSave="SaveAppearance" />
                        break;
                }
            }
        </div>
    </div>
</div>

@code {
    private string _activeSection = "Profile";
    private bool _loading = true;

    private UserProfile? _profile;
    private NotificationPrefs? _notificationPrefs;
    private SecuritySettings? _securitySettings;
    private AppearanceSettings? _appearanceSettings;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
